static volatile MTC_Regs_3113c_t *p_mtc_reg = (volatile MTC_Regs_3113c_t *)0x00fc0000;

static unsigned int swap32(unsigned int x)
{
    unsigned int r = 0;

    r |= (x>>24)&0xFF;
    r |= ((x>>16)&0xFF)<<8;
    r |= ((x>>8)&0xFF)<<16;
    r |= ((x)&0xFF)<<24;

    return r;
}

static int gx_mtc_set_mode(enum mtc_algorithm algorithm, enum mtc_sub_mode sub_mode)
{
	switch (algorithm) {
	case GXMTC_DES :
		MTC_SET_ALGO_DES(p_mtc_reg);
		break;
	case GXMTC_3DES:
		MTC_SET_ALGO_3DES(p_mtc_reg);
		break;
	case GXMTC_AES128:
		MTC_SET_ALGO_AES128(p_mtc_reg);
		break;
	case GXMTC_AES192:
		MTC_SET_ALGO_AES192(p_mtc_reg);
		break;
	case GXMTC_AES256:
		MTC_SET_ALGO_AES256(p_mtc_reg);
		break;
	case GXMTC_MULTI2:
		MTC_SET_ALGO_MULTI2(p_mtc_reg);
		break;
	case GXMTC_SMS4:
		MTC_SET_ALGO_SMS4(p_mtc_reg);
		break;
	default:
		return -1;
	}

	if (sub_mode > GXMTC_CTR)
		return -1;
	else
		MTC_SET_SUB_MODE(p_mtc_reg, sub_mode);

	return 0;
}

/*
 * 对于长度为 6 * 4 个字节的dck dsk 的处理
 */
static int gx_mtc_set_ca_data(unsigned int base_addr, unsigned char *buf, int size)
{
	switch (size) {
	case 8:
		MTC_SET_CA_DATA_4(base_addr, (buf[3] | (buf[2] << 8) | (buf[1] << 16) | (buf[0] << 24)));
		MTC_SET_CA_DATA_5(base_addr, (buf[7] | (buf[6] << 8) | (buf[5] << 16) | (buf[4] << 24)));
		break;
	case 16:
		MTC_SET_CA_DATA_2(base_addr, ( buf[3] |  (buf[2] << 8) |  (buf[1] << 16) |  (buf[0] << 24)));
		MTC_SET_CA_DATA_3(base_addr, ( buf[7] |  (buf[6] << 8) |  (buf[5] << 16) |  (buf[4] << 24)));
		MTC_SET_CA_DATA_4(base_addr, (buf[11] | (buf[10] << 8) |  (buf[9] << 16) |  (buf[8] << 24)));
		MTC_SET_CA_DATA_5(base_addr, (buf[15] | (buf[14] << 8) | (buf[13] << 16) | (buf[12] << 24)));
		break;
	case 24:
		MTC_SET_CA_DATA_0(base_addr, ( buf[3] |  (buf[2] << 8) |  (buf[1] << 16) |  (buf[0] << 24)));
		MTC_SET_CA_DATA_1(base_addr, ( buf[7] |  (buf[6] << 8) |  (buf[5] << 16) |  (buf[4] << 24)));
		MTC_SET_CA_DATA_2(base_addr, (buf[11] | (buf[10] << 8) |  (buf[9] << 16) |  (buf[8] << 24)));
		MTC_SET_CA_DATA_3(base_addr, (buf[15] | (buf[14] << 8) | (buf[13] << 16) | (buf[12] << 24)));
		MTC_SET_CA_DATA_4(base_addr, (buf[19] | (buf[18] << 8) | (buf[17] << 16) | (buf[16] << 24)));
		MTC_SET_CA_DATA_5(base_addr, (buf[23] | (buf[22] << 8) | (buf[21] << 16) | (buf[20] << 24)));
		break;
	default:
		return -1;
	}

	return 0;
}

/*
 *  长度为 4 * 4 个字节的 dcw 数据配置
 */
static int gx_mtc_set_ca_data_dcw(unsigned int base_addr, unsigned char *buf, int size)
{
	switch (size) {
	case 8:
		MTC_SET_CA_DATA_DCW_2(base_addr, (buf[3] | (buf[2] << 8) | (buf[1] << 16) | (buf[0] << 24)));
		MTC_SET_CA_DATA_DCW_3(base_addr, (buf[7] | (buf[6] << 8) | (buf[5] << 16) | (buf[4] << 24)));
		break;
	case 16:
		MTC_SET_CA_DATA_DCW_0(base_addr, ( buf[3]  |  (buf[2] << 8) |  (buf[1] << 16) |  (buf[0] << 24)));
		MTC_SET_CA_DATA_DCW_1(base_addr, ( buf[7]  |  (buf[6] << 8) |  (buf[5] << 16) |  (buf[4] << 24)));
		MTC_SET_CA_DATA_DCW_2(base_addr, ( buf[11] | (buf[10] << 8) |  (buf[9] << 16) |  (buf[8] << 24)));
		MTC_SET_CA_DATA_DCW_3(base_addr, ( buf[15] | (buf[14] << 8) | (buf[13] << 16) | (buf[12] << 24)));
		break;
	default:
		return -1;
	}

	return 0;
}

static int gx_mtc_set_round_and_data(struct mtc_input_s *input)
{
	switch (input->num) {
	case 1:
		MTC_SET_ONE_ROUND(p_mtc_reg);
		MTC_SET_CW_ENABLE(p_mtc_reg);

		gx_mtc_set_ca_data_dcw((unsigned int)&p_mtc_reg->MTC_DCW[0], input->buf[0], input->size[0]);

		MTC_SET_ONE_ROUND_READY(p_mtc_reg);
		break;
	case 2:
		MTC_SET_TWO_ROUND(p_mtc_reg);
		MTC_SET_CW_ENABLE(p_mtc_reg);

		gx_mtc_set_ca_data((unsigned int)&p_mtc_reg->MTC_DCK[0], input->buf[0], input->size[0]);
		gx_mtc_set_ca_data_dcw((unsigned int)&p_mtc_reg->MTC_DCW[0], input->buf[1], input->size[1]);

		MTC_SET_TWO_ROUND_READY(p_mtc_reg);
		break;
	case 3:
		MTC_SET_THREE_ROUND(p_mtc_reg);
		MTC_SET_CW_ENABLE(p_mtc_reg);

		gx_mtc_set_ca_data((unsigned int)&p_mtc_reg->MTC_DSK[0], input->buf[0], input->size[0]);
		gx_mtc_set_ca_data((unsigned int)&p_mtc_reg->MTC_DCK[0], input->buf[1], input->size[1]);
		gx_mtc_set_ca_data_dcw((unsigned int)&p_mtc_reg->MTC_DCW[0], input->buf[2], input->size[2]);

		MTC_SET_THREE_ROUND_READY(p_mtc_reg);
		break;
	case 4:
	case 5:
	default :
		return -1;
	}
	return 0;
}

static void gx_mtc_set_sht_and_residue(enum mtc_short_msg sht, enum mtc_residue_msg res)
{
	switch (sht) {
	case MTC_SHO_CLEAR:
		MTC_SET_SHORT_MSG(p_mtc_reg, MTC_SHO_CLEAR);
		break;
	case MTC_SHO_IV:
		MTC_SET_SHORT_MSG(p_mtc_reg, MTC_SHO_IV);
		break;
	case MTC_SHO_IV2:
		MTC_SET_SHORT_MSG(p_mtc_reg, MTC_SHO_IV2);
		break;
	default :
		MTC_SET_SHORT_MSG(p_mtc_reg, MTC_SHO_CLEAR);
		break;
	}

	switch (res) {
	case MTC_RES_CLEAR:
		MTC_SET_RESIDUE_MSG(p_mtc_reg, MTC_RES_CLEAR);
		break;
	case MTC_RES_CTS:
		MTC_SET_RESIDUE_MSG(p_mtc_reg, MTC_RES_CTS);
		break;
	case MTC_RES_RBT:
		MTC_SET_RESIDUE_MSG(p_mtc_reg, MTC_RES_RBT);
		break;
	default :
		MTC_SET_RESIDUE_MSG(p_mtc_reg, MTC_RES_CLEAR);
		break;
	}
}


static int gx_mtc_set_core_ready(enum mtc_algorithm algorithm)
{
	switch (algorithm) {
	case GXMTC_DES:
	case GXMTC_3DES:
		MTC_SET_DES_READY(p_mtc_reg);
		break;
	case GXMTC_AES128:
	case GXMTC_AES192:
	case GXMTC_AES256:
		MTC_SET_AES_READY(p_mtc_reg);
		break;
	case GXMTC_MULTI2:
		MTC_SET_MULTI2_READY(p_mtc_reg);
		break;
	case GXMTC_SMS4:
		MTC_SET_SMS4_READY(p_mtc_reg);
		break;
	default :
		return -1;
	}

	return 0;
}

static int flag_timed_wait(uint32_t timeout)
{
	uint32_t start = 0;
	uint32_t end = 0;
	gx_mtc_extra *extra = &mtc_extra;

	start = gx_time_get_ms();
	do {
		if (extra->sync_flag) {
			extra->sync_flag = 0;
			return 1;
		}
		end = gx_time_get_ms();
	} while((end - start) < timeout);

	return 0;
}

static void gx_mtc_wait_finish(void)
{
	gx_mtc_extra *extra = &mtc_extra;
	uint32_t start = 0;
	uint32_t end = 0;
	uint32_t ret = GXMTC_DEFAULT_STATUS;

	extra->result = GXMTC_NOERR;
	start = gx_time_get_ms();
	do {
		ret = MTC_ALL_INT_STATUS_GET(p_mtc_reg);
		if (ret)
			break;
		end = gx_time_get_ms();
	} while ((end - start) < MTC_WAIT_TIMEOUT_MS);

	if (!ret) {
		extra->result = GXMTC_TIMEOUT;
		MTC_DBG("mtc time out , in  %s %d \n", __FILE__, __LINE__);
		return ;
	}

	if (ret & GXMTC_NDS_OPERATE_ERROR) {
		extra->result = GXMTC_ERROR;
		MTC_DBG("mtc nds operate error\n");
		return ;
	} else if (ret & GXMTC_M2MKEY_RW_SPACE_ERROR) {
		extra->result = GXMTC_ERROR;
		MTC_DBG("mtc m2mkey read or write space error\n");
		return ;
	} else if (ret & GXMTC_MEMORY_KEY_RD_SPACE_ERROR) {
		extra->result = GXMTC_ERROR;
		MTC_DBG("mtc memory key read space error\n");
		return ;
	} else if (ret & GXMTC_DATA_FINISH) {
		return ;
	} else if (ret & GXMTC_K3_FINISH) {
		return ;
	} else if (ret & GXMTC_AES_ROUND_FINISH) {
		return ;
	} else if (ret & GXMTC_TDES_ROUND_FINISH) {
		return ;
	} else if (ret & GXMTC_MEMORY_KEY_RD_FINISH) {
		return ;
	}

	extra->result = GXMTC_ERROR;
	return ;
}

static int gx_mtc_finish_operate(void)
{
	MTC_CLR_CTRL1(p_mtc_reg);
	MTC_CLR_CTRL2(p_mtc_reg);
	MTC_ALL_INT_DISABLE(p_mtc_reg);
	MTC_CLR_ALL_INT_STATUS(p_mtc_reg);
	MTC_CLR_CA_MODE_REG(p_mtc_reg);
	MTC_CLR_CW_SELECT_REG(p_mtc_reg);
	return 0;
}

static int check_alignment(struct mtc_data_s *mtc_data)
{
	unsigned int addr_check;
	int i;

	// 地址检查
	for (i = 0; i < mtc_data->input.num; i++) {
		addr_check = (int)mtc_data->input.buf[i];
		if (addr_check % 64 != 0)
			return -EIO;
	}

	addr_check = (int)mtc_data->output.buf;
	if (addr_check % 64 != 0)
		return -EIO;

	// 数据长度对齐检查
	switch (mtc_data->algorithm) {
	case GXMTC_DES:
	case GXMTC_3DES:
		{
			for (i = 0; i < mtc_data->input.num; i++)
				if (mtc_data->input.size[i] % 8 != 0)
					return -EIO;
		}
		break;
	case GXMTC_AES128:
	case GXMTC_AES192:
	case GXMTC_AES256:
		{
			for (i = 0; i < mtc_data->input.num; i++)
				if (mtc_data->input.size[i] % 16 != 0)
					return -EIO;
		}
		break;
	default :
		break;
	}

	return 0;
}

static int gx_mtc_set_counter(struct mtc_data_s *mtc_data)
{
	if (mtc_data->algorithm != GXMTC_DES && \
			mtc_data->algorithm != GXMTC_3DES)
		return 0;

	if (mtc_data->sub_mode != GXMTC_CTR)
		return 0;

	int *p_counter = (int *)mtc_data->mtc_counter.value;
	int counter_len = mtc_data->mtc_counter.len;
	switch (counter_len) {
	case 8:
		MTC_SET_COUNTER_63_32(p_mtc_reg, swap32(p_counter[0]));
		MTC_SET_COUNTER_31_0(p_mtc_reg, swap32(p_counter[1]));
		break;
	default:
		break;
	}

	return 0;
}

static int gx_mtc_set_iv(struct mtc_data_s *mtc_data)
{
    int *iv = (int *)mtc_data->mtc_iv.iv_value;
    int iv_len = mtc_data->mtc_iv.iv_len;
    enum mtc_sub_mode sub_mode = mtc_data->sub_mode;
    enum mtc_algorithm algo = mtc_data->algorithm;

    if (sub_mode == GXMTC_CBC || sub_mode == GXMTC_OFB || sub_mode == GXMTC_CFB) {
        switch (algo) {
        case GXMTC_DES:
        case GXMTC_3DES:
            {
                switch (iv_len) {
                case 8:
                    p_mtc_reg->MTC_IV1[3] = swap32(iv[1]);
                    p_mtc_reg->MTC_IV1[2] = swap32(iv[0]);
                    break;
                case 16:
                    p_mtc_reg->MTC_IV1[3] = swap32(iv[1]);
                    p_mtc_reg->MTC_IV1[2] = swap32(iv[0]);
                    p_mtc_reg->MTC_IV1[1] = swap32(iv[3]);
                    p_mtc_reg->MTC_IV1[0] = swap32(iv[2]);
                    break;
                default :
                    MTC_DBG ("iv size not right\n");
                    return -1;
                }
            }
            break;
        case GXMTC_AES128:
        case GXMTC_AES192:
        case GXMTC_AES256:
            {
                switch (iv_len) {
                case 8:
                    p_mtc_reg->MTC_IV1[3] = swap32(iv[1]);
                    p_mtc_reg->MTC_IV1[2] = swap32(iv[0]);
                    break;
                case 16:
                    p_mtc_reg->MTC_IV1[3] = swap32(iv[3]);
                    p_mtc_reg->MTC_IV1[2] = swap32(iv[2]);
                    p_mtc_reg->MTC_IV1[1] = swap32(iv[1]);
                    p_mtc_reg->MTC_IV1[0] = swap32(iv[0]);
                    break;
                default :
                    MTC_DBG ("iv size not right\n");
                    return -1;
                }
            }
            break;
        default :
            break;
        }
    }

    return 0;
}

static int gx_mtc_set_key(struct mtc_data_s *mp)
{
	int *p_key;
	int key_len;
	enum mtc_algorithm algo;

	p_key = (int *)mp->mtc_key.key_value;
	key_len = mp->mtc_key.key_len;
	algo = mp->algorithm;

	switch (algo) {
	case GXMTC_DES:
	case GXMTC_3DES:
		{
			switch (key_len) {
			case 8:
				MTC_SET_KEY_31_0(p_mtc_reg, swap32(p_key[1]));
				MTC_SET_KEY_63_32(p_mtc_reg, swap32(p_key[0]));
				break;
			case 16:
				MTC_SET_KEY_31_0(p_mtc_reg, swap32(p_key[1]));
				MTC_SET_KEY_63_32(p_mtc_reg, swap32(p_key[0]));
				MTC_SET_KEY_95_64(p_mtc_reg, swap32(p_key[3]));
				MTC_SET_KEY_127_96(p_mtc_reg, swap32(p_key[2]));
				break;
			case 24:
				MTC_SET_KEY_31_0(p_mtc_reg, swap32(p_key[1]));
				MTC_SET_KEY_63_32(p_mtc_reg, swap32(p_key[0]));
				MTC_SET_KEY_95_64(p_mtc_reg, swap32(p_key[3]));
				MTC_SET_KEY_127_96(p_mtc_reg, swap32(p_key[2]));
				MTC_SET_KEY_159_128(p_mtc_reg, swap32(p_key[5]));
				MTC_SET_KEY_191_160(p_mtc_reg, swap32(p_key[4]));
				break;
			case 32:
				MTC_SET_KEY_31_0(p_mtc_reg, swap32(p_key[1]));
				MTC_SET_KEY_63_32(p_mtc_reg, swap32(p_key[0]));
				MTC_SET_KEY_95_64(p_mtc_reg, swap32(p_key[3]));
				MTC_SET_KEY_127_96(p_mtc_reg, swap32(p_key[2]));
				MTC_SET_KEY_159_128(p_mtc_reg, swap32(p_key[5]));
				MTC_SET_KEY_191_160(p_mtc_reg, swap32(p_key[4]));
				MTC_SET_KEY_223_192(p_mtc_reg, swap32(p_key[7]));
				MTC_SET_KEY_255_224(p_mtc_reg, swap32(p_key[6]));
				break;
			default:
				break;
			}
		}
		break;
	case GXMTC_AES128:
	case GXMTC_AES192:
	case GXMTC_AES256:
		{
			switch (key_len) {
			case 16:
				MTC_SET_KEY_127_96(p_mtc_reg, swap32(p_key[0]));
				MTC_SET_KEY_95_64(p_mtc_reg, swap32(p_key[1]));
				MTC_SET_KEY_63_32(p_mtc_reg, swap32(p_key[2]));
				MTC_SET_KEY_31_0(p_mtc_reg, swap32(p_key[3]));
				break;
			case 24:
				MTC_SET_KEY_191_160(p_mtc_reg, swap32(p_key[0]));
				MTC_SET_KEY_159_128(p_mtc_reg, swap32(p_key[1]));
				MTC_SET_KEY_127_96(p_mtc_reg, swap32(p_key[2]));
				MTC_SET_KEY_95_64(p_mtc_reg, swap32(p_key[3]));
				MTC_SET_KEY_63_32(p_mtc_reg, swap32(p_key[4]));
				MTC_SET_KEY_31_0(p_mtc_reg, swap32(p_key[5]));
				break;
			case 32:
				MTC_SET_KEY_255_224(p_mtc_reg, swap32(p_key[0]));
				MTC_SET_KEY_223_192(p_mtc_reg, swap32(p_key[1]));
				MTC_SET_KEY_191_160(p_mtc_reg, swap32(p_key[2]));
				MTC_SET_KEY_159_128(p_mtc_reg, swap32(p_key[3]));
				MTC_SET_KEY_127_96(p_mtc_reg, swap32(p_key[4]));
				MTC_SET_KEY_95_64(p_mtc_reg, swap32(p_key[5]));
				MTC_SET_KEY_63_32(p_mtc_reg, swap32(p_key[6]));
				MTC_SET_KEY_31_0(p_mtc_reg, swap32(p_key[7]));
				break;
			default :
				break;
			}
		}
		break;
	default :
		break;
	}

	MTC_SET_KEY_READY(p_mtc_reg);
	return 0;
}

static int gx_mtc_set_buf(unsigned int src_buf_addr, int src_buf_len, unsigned int dst_buf_addr)
{
    MTC_SET_READ_BUF_ADDR(p_mtc_reg, src_buf_addr);
    MTC_SET_READ_BUF_LEN(p_mtc_reg, src_buf_len);
    MTC_SET_WRITE_BUF_ADDR(p_mtc_reg, dst_buf_addr);
    return 0;
}

static void gx_mtc_set_ca_addr(int ca_id, enum mtc_cw_odd_even odd_even)
{
	if (odd_even == GXMTC_CW_EVEN_FIRST)
		MTC_SET_CA_ADDR_EVEN(p_mtc_reg, ca_id);
	else
		MTC_SET_CA_ADDR_ODD(p_mtc_reg, ca_id);
}

enum interrupt_return mtc_interrupt_isr(unsigned int vector, void *pdata)
{
	gx_mask_irq(vector);
	gx_mtc_extra *extra = (gx_mtc_extra *)pdata;
	extra->result = MTC_ALL_INT_STATUS_GET(p_mtc_reg);
	extra->sync_flag = 1;
	MTC_CLR_ALL_INT_STATUS(p_mtc_reg);
	gx_unmask_irq(vector);
	return HANDLED;
}

static int gx3113c_mtc_get_max_buf_len(void)
{
	// 64 Bytes align requirement
	return (MTC_MAX_BUF_LEN / 64) * 64;
}

static int gx3113c_mtc_core_data_en_or_decrypt(struct mtc_data_s *mtc_data, int is_encrypt, struct mtc_input_s *ip, \
		struct mtc_output_s *op)
{
	gx_mtc_extra *extra = &mtc_extra;

	if (is_encrypt)
		MTC_SET_ENCRYPT(p_mtc_reg);
	else
		MTC_SET_DECRYPT(p_mtc_reg);

	MTC_SET_KEY_SELECT(p_mtc_reg, KEY_SELECT_KEY_IPBUS_SET);
	gx_mtc_set_mode(mtc_data->algorithm, mtc_data->sub_mode);
	gx_mtc_set_counter(mtc_data);
	gx_mtc_set_iv(mtc_data);
	gx_mtc_set_key(mtc_data);
	gx_mtc_set_buf((unsigned int)ip->buf[0], ip->size[0], (unsigned int)op->buf);
	dcache_flush();
	gx_mtc_set_core_ready(mtc_data->algorithm);
	gx_mtc_wait_finish();
	gx_mtc_finish_operate();
	dcache_flush();

	HANDLE_ERROR(extra->result);
}

static int gx3113c_mtc_core_data_encrypt_or_decrypt(struct mtc_data_s *mtc_data, int is_encrypt)
{
	int max_size_each_time, total_size, offset;
	struct mtc_input_s ip;
	struct mtc_output_s op;
	int ret;

	ret = check_alignment(mtc_data);
	if (ret != 0)
		return ret;

	offset = 0;
	total_size = mtc_data->input.size[0];
	max_size_each_time = gx3113c_mtc_get_max_buf_len();

	while (total_size > 0) {
		ip.size[0] = total_size < max_size_each_time ? total_size : max_size_each_time;
		ip.buf[0]  = mtc_data->input.buf[0] + offset;
		op.buf     = mtc_data->output.buf   + offset;

		ret = gx3113c_mtc_core_data_en_or_decrypt(mtc_data, is_encrypt, &ip, &op);
		if (ret != 0)
			break;

		total_size -= ip.size[0];
		offset     += ip.size[0];
	}

	return ret;
}

int gx_mtc_core_data_decrypt(struct mtc_data_s *mtc_data)
{
	return gx3113c_mtc_core_data_encrypt_or_decrypt(mtc_data, DO_DECRYPT);
}

int gx_mtc_core_data_encrypt(struct mtc_data_s *mtc_data)
{
	return gx3113c_mtc_core_data_encrypt_or_decrypt(mtc_data, DO_ENCRYPT);
}

int gx_mtc_core_cw_decrypt(struct mtc_data_s *mtc_data)
{
	gx_mtc_extra *extra = &mtc_extra;

	MTC_SET_CA_MODE(p_mtc_reg);
	gx_mtc_set_mode(mtc_data->algorithm, mtc_data->sub_mode);
	gx_mtc_set_sht_and_residue(mtc_data->sht_msg, mtc_data->res_msg);
	MTC_SET_DECRYPT(p_mtc_reg);
	gx_mtc_set_ca_addr(*(int *)mtc_data->output.buf, mtc_data->odd_even);
	gx_mtc_set_round_and_data(&mtc_data->input);
	dcache_flush();
	MTC_SET_KEY_READY(p_mtc_reg);
	gx_mtc_set_core_ready(mtc_data->algorithm);
	gx_mtc_wait_finish();
	gx_mtc_finish_operate();
	dcache_flush();

	HANDLE_ERROR(extra->result);
}
